-- ============================================================
-- KOJOH: seed for "Late Again: Last-Mile Delivery in Tier-2 India"  (slug: late-again-last-mile-fy2526)
-- Safe to run more than once. Run AFTER schema-marketplace.sql and schema-preview.sql.
-- Also create the storage folder datasets/late-again-last-mile-fy2526/ and upload the files in
-- storage_upload/late-again-last-mile-fy2526/ (csv, xlsx, dictionary, story).
-- ============================================================

insert into public.datasets (folder_id, slug, title, short_description, long_description,
                              price, is_free, difficulty, storage_path)
select f.id, 'late-again-last-mile-fy2526', 'Late Again: Last-Mile Delivery in Tier-2 India',
  'A year of messy dispatch exports from a fictional regional courier serving the small cities of UP, Bihar, Jharkhand and MP: 14,560 shipments, 41 columns, 48 riders, 12 hubs, 6 shippers. Clean it, then settle the argument operations can''t: why the on-time number is wrong, why a rider with perfect first attempts is the network''s biggest problem, and which hub, which day and which parcel size are quietly costing the business its largest client.',
  'Raahi Express is a regional last-mile courier serving the small cities and towns of Uttar Pradesh, Bihar, Jharkhand and Madhya Pradesh. Twelve destination hubs (Lucknow, Kanpur, Varanasi, Gorakhpur, Prayagraj, Agra, Bareilly, Patna, Muzaffarpur, Gaya, Ranchi and Bhopal) each run four riders and serve a hub city plus the towns around it. Six shippers feed the network: a large marketplace, two D2C brands, a pharmacy, an apparel seller and a hardware wholesaler. Parcels are picked up in Delhi, Kolkata or Mumbai, line-hauled to the destination hub, and then attempted by the rider up to three times before they are returned to the shipper. Every shipment leaves a trail in the dispatch system: pickup, the promised delivery date, hub arrival, each attempt, the final outcome, what was billed and what the journey cost. The financial year just closed on 31 March 2026, and the largest shipper, Apnabazaar, has put the contract up for review. The Operations Head is confident. His dashboard says **92.3% of shipments are delivered on time**, and he wants to name **Mohit Tiwari** of the Lucknow hub "Rider of the Year". The rider handled more parcels than anyone in the network (735) and his first attempts are almost always made on or before the promised date (98.9%, the best of 48 riders).',
  99.00, false, 'hard', 'late-again-last-mile-fy2526'
from public.folders f
where f.slug = 'data-analyst'
on conflict (slug) do nothing;

insert into public.dataset_job_titles (dataset_id, job_title_id)
select d.id, jt.id from public.datasets d, public.job_titles jt
where d.slug = 'late-again-last-mile-fy2526' and jt.name = 'Data Analyst'
on conflict do nothing;

insert into public.dataset_tags (dataset_id, tag_id)
select d.id, t.id from public.datasets d, public.tags t
where d.slug = 'late-again-last-mile-fy2526' and t.name in ('Python', 'SQL', 'Excel', 'Logistics')
on conflict do nothing;

insert into public.dataset_schema (dataset_id, column_name, column_type, description, sort_order)
select d.id, col.column_name, col.column_type, col.description, col.sort_order
from public.datasets d
cross join (values
  ('AWB No', 'text', 'Air waybill number, e.g. `RX81000042`. Not unique: about 190 shipments were entered twice and carry the same AWB.', 1),
  ('Pickup Date', 'text (mixed date formats)', 'When the shipment was collected from the shipper. Five mixed formats (see the note below).', 2),
  ('Promised Delivery Date', 'text (mixed date formats)', 'The date promised to the shipper (the SLA). Five mixed formats.', 3),
  ('Hub Arrival Date', 'text (mixed date formats)', 'When the parcel reached the destination hub. Five mixed formats. Blank for some Lost shipments and for shipments still open.', 4),
  ('First Attempt Date', 'text (mixed date formats)', 'Date of the first delivery attempt. Five mixed formats. Blank for Lost shipments.', 5),
  ('Second Attempt Date', 'text (mixed date formats)', 'Date of the second attempt, if there was one. Five mixed formats.', 6),
  ('Final Status Date', 'text (mixed date formats)', 'Date the shipment reached its final outcome. Five mixed formats. Blank for Lost and open shipments. A few rows fall before the pickup date.', 7),
  ('Month', 'text', 'Pickup month label, e.g. `Oct-25`. **~40% blank.** Derive it from Pickup Date instead.', 8),
  ('Shipper', 'text', 'Client that booked the shipment. 5 spellings each: `Apna Bazaar`, `apnabazaar.com`, `GKS`, `TB Apparel`.', 9),
  ('Shipper Segment', 'text', 'Marketplace, D2C Brand, Pharma or B2B. 3 to 4 spellings each.', 10),
  ('Origin Hub', 'text', 'Delhi (Gurugram), Kolkata or Mumbai. Clean.', 11),
  ('Destination Hub', 'text', 'One of 12 destination hubs. ~5% upper-cased.', 12),
  ('Destination City', 'text', 'Delivery town. Case noise and abbreviations (`GKP`-style three-letter forms).', 13),
  ('State', 'text', 'Delivery state. ~12% upper-cased.', 14),
  ('Pincode', 'text', 'Delivery pincode. `273001`, `273001.0` or `273 001`.', 15),
  ('Zone', 'text', 'B (hub city), C (nearby town) or D (remote town). `B`, `Zone B`, `ZONE-B`, `zone b`, `B `', 16),
  ('Service Type', 'text', 'Express, Standard or Economy. 5 spellings each: `Exp`, `Std`, `Eco Surface`.', 17),
  ('Weight', 'text (mixed units)', 'Parcel weight. `0.5`, `0.50 kg`, `500 g`, `0.5kg`, `500gm`. A handful of zeros.', 18),
  ('Declared Value', 'text (mixed currency formats)', 'Value declared by the shipper. Money text in several formats.', 19),
  ('Payment Type', 'text', 'Prepaid or COD. 5 spellings each: `Cash on Delivery`, `PP`, `Pre-paid`.', 20),
  ('COD Amount', 'text (mixed currency formats)', 'Cash to collect on delivery. Blank (or `0`) for prepaid.', 21),
  ('Freight Charge', 'text (mixed currency formats)', 'Base freight billed. Money text; ~10 rows swapped with Linehaul Cost.', 22),
  ('Fuel Surcharge', 'text (mixed currency formats)', '12% of freight. ~3% blank.', 23),
  ('COD Fee', 'text (mixed currency formats)', 'Fee for collecting cash. Blank for prepaid.', 24),
  ('Total Billed', 'text (mixed currency formats)', 'What the shipper is charged. A few negative values. Zero for Lost shipments.', 25),
  ('Linehaul Cost', 'text (mixed currency formats)', 'Cost to move the parcel to the hub, including hub handling. ~3% blank.', 26),
  ('Last Mile Cost', 'text (mixed currency formats)', 'Rider payout for the first attempt. ~4% blank.', 27),
  ('Reattempt Cost', 'text (mixed currency formats)', 'Rider payout for second and third attempts. Blank vs `0` when none.', 28),
  ('RTO Cost', 'text (mixed currency formats)', 'Cost of returning the parcel to the shipper. Blank unless RTO.', 29),
  ('Claim Paid', 'text (mixed currency formats)', 'Compensation paid to the shipper for Lost or Damaged parcels. Blank unless Lost or Damaged.', 30),
  ('Attempts', 'text', 'Number of delivery attempts made. `2`, `2 attempts`, `Two`.', 31),
  ('Delivery Status', 'text', 'Delivered, RTO, Lost, Damaged or In Transit. **~28 spellings** of five outcomes: `DLVD`, `Delivered - POD OK`, `Return to Origin`, `Missing`, `Hub Hold`.', 32),
  ('NDR Reason', 'text', 'Reason logged for the first failed attempt (non-delivery report). Blank when the first attempt succeeded.', 33),
  ('Rider Name', 'text (free-text, many spellings)', 'Free-text name of the delivering rider. **The key trap.** Each of 48 riders appears under ~8 spellings.', 34),
  ('Rider ID', 'text', 'Rider code, e.g. `R2013`. ~6% blank, ~3% lowercase, ~2% typo''d (`R02013`). Don''t trust either field alone.', 35),
  ('Vehicle Type', 'text', 'Bike, EV Scooter or Van. Clean.', 36),
  ('Route Cluster', 'text', 'Hub-and-number delivery cluster, e.g. `GKP-03`. Clean.', 37),
  ('Proof of Delivery', 'text', 'OTP, Signature, Photo or None. None for failed attempts.', 38),
  ('Escalation', 'text', 'Whether the customer or shipper escalated. ~10% lowercase.', 39),
  ('CSAT', 'text', 'Customer satisfaction score, 1 to 5. Blank on most shipments (only about 3,991 answered).', 40),
  ('Remarks', 'text', 'Free-text note from the hub. Mostly blank.', 41)
) as col(column_name, column_type, description, sort_order)
where d.slug = 'late-again-last-mile-fy2526'
and not exists (select 1 from public.dataset_schema s where s.dataset_id = d.id);

alter table public.datasets add column if not exists preview_rows jsonb;
alter table public.datasets add column if not exists locked_preview jsonb;

update public.datasets
set preview_rows = $prev${"columns": ["AWB No", "Pickup Date", "Promised Delivery Date", "Hub Arrival Date", "First Attempt Date", "Second Attempt Date", "Final Status Date", "Month", "Shipper", "Shipper Segment", "Origin Hub", "Destination Hub", "Destination City", "State", "Pincode", "Zone", "Service Type", "Weight", "Declared Value", "Payment Type", "COD Amount", "Freight Charge", "Fuel Surcharge", "COD Fee", "Total Billed", "Linehaul Cost", "Last Mile Cost", "Reattempt Cost", "RTO Cost", "Claim Paid", "Attempts", "Delivery Status", "NDR Reason", "Rider Name", "Rider ID", "Vehicle Type", "Route Cluster", "Proof of Delivery", "Escalation", "CSAT", "Remarks"], "rows": [["RX81004729", "19/04/2025", "23/04/2025", "21 Apr 2025", "22-04-25", "", "22/04/2025", "Apr-25", "Apnabazaar", "Marketplace", "Delhi (Gurugram)", "Bhopal", "Bhopal", "Madhya Pradesh", "462443", "B", "Standard", "600gm", "₹1990", "Prepaid", "0", "55", "₹7", "", "62", "33", "₹28", "", "", "", "1", "Shipment Delivered", "", "S. Rai", "R2048", "EV Scooter", "BHO-02", "OTP", "No", "", "gate pass needed"], ["RX81018141", "45820", "2025-06-15", "13-06-25", "13 Jun 2025", "2025-06-14", "14-06-25", "", "MEDIQUICK", "Pharma", "Delhi (Gurugram)", "Kanpur", "Kanpur", "Uttar Pradesh", "208461", "B", "Express", "0.95kg", "₹2050", "prepaid", "", "Rs 77", "Rs 9", "", "86", "33", "28.00", "₹28", "", "", "2", "Delivered", "Customer Not Available", "Deepak Bind ", "R2006", "Bike", "KAN-01", "OTP", "No", "4", ""], ["RX81043012", "2025-09-15", "45919", "16 Sep 2025", "18 Sep 2025", "", "2025-09-18", "Sep-25", "NaturalGlow", "D2C Brand", "Delhi (Gurugram)", "Bareilly", "Bareilly", "Uttar Pradesh", "243394", "B", "Standard", "200 g", "1,030", "Prepaid", "", "Rs 44", "5", "", "49", "33", "Rs 28", "", "", "", "One", "delivered", "", "Zakir V", "R2027", "Bike", "BAR-05", "Photo", "No", "", ""], ["RX81023713", "2025-07-03", "07-07-25", "05-07-25", "2025-07-06", "", "06-07-25", "Jul-25", "TH Hardware", "B2B Hardware", "Delhi (Gurugram)", "Gaya", "Gaya", "BIHAR", "823122", "Zone B", "Standard", "11.5", "8020.00", "Prepaid", "", "305.00", "  37  ", "", "342", "Rs 88", "Rs 28", "", "", "", "1", "Delivered", "", "lokesh ansari", "", "Bike", "GAY-01", "OTP", "No", "", ""], ["RX81019399", "17/06/2025", "2025-06-21", "19/06/2025", "21/06/2025", "", "21/06/2025", "Jun-25", "Apnabazaar", "Marketplace", "Delhi (Gurugram)", "Gaya", "GAY", "Bihar", "823072.0", "B", "Standard", "2000gm", "₹2260", "PP", "", "70", "Rs 8", "", "78", "  33  ", "28", "0", "", "", "1 attempt", "Shipment Delivered", "", "mukesh pandey", "R2040", "EV Scooter", "GAY-04", "OTP", "No", "", ""]], "total_rows": 14750}$prev$::jsonb,
    locked_preview = $lock${"summary": "A full four phase operations project built on 14,750 rows across 41 columns of messy dispatch exports from a fictional regional courier. You clean it, you query it, you build a two page dashboard on it, then you write the recommendation that explains why the on-time number is wrong.", "phases": [{"title": "Phase 1, Python: Clean the Data", "blurb": "Turn the raw dispatch export into a trustworthy table. Nothing later works until this does.", "count": 8, "sample": ["Load the raw CSV/XLSX and profile it: row count, column count, null counts per column, and a written note on the five things that look most wrong before you touch anything.", "Remove duplicate shipment entries (~190 of them). State your de-duplication rule and how many genuine shipments remain."]}, {"title": "Phase 2, SQL: Answer the Business Questions", "blurb": "Settle the arguments operations cannot settle themselves, with evidence.", "count": 12, "sample": ["Reproduce the Ops dashboard's on-time figure: the share of shipments whose FIRST ATTEMPT date is on or before the promised date (among shipments that had an attempt), per month and overall.", "Compute the on-time figure a shipper would compute: Delivered shipments with a final status date on or before the promised date, as a share of all shipments that reached a final status (exclude In Transit). Show it next to S1 per month and report the gap."]}, {"title": "Phase 3a, Dashboard Page 1: Shipment Lookup", "blurb": "Type an AWB, get the whole journey, the promise and the profit on that parcel.", "count": 5, "sample": ["Build a search box that takes an AWB number and shows the whole journey on one screen: pickup, hub arrival, each attempt, final status, with the promised date marked and the delay (or slack) called out, plus the billing waterfall (billed minus each cost = profit).", "On the same screen show context: shipper, service and zone, rider and vehicle, NDR reasons, proof of delivery, escalation flag, CSAT and remarks."]}, {"title": "Phase 3b, Dashboard Page 2: Analytics", "blurb": "The analytics page a network head actually lives in.", "count": 10, "sample": ["Build a rider scorecard showing volume, first-attempt on-time %, true on-time %, RTO % and escalation rate side by side, so 'best rider' is never reduced to one number.", "Add a monthly trend panel with the dashboard's on-time % and the true on-time % on the same chart, so the gap between them is the story."]}, {"title": "Phase 4, Documentation", "blurb": "Write the recommendation you would actually hand an operations director.", "count": 1, "sample": ["Write a short project write-up (any format: Word, PDF, Notion, a README) with three sections: (1) **Process Flow**: how you went from the raw export to cleaned data to SQL answers to your dashboard, including the decisions you made, especially how you resolved rider identity and treated the cut-off; (2) **Key Discoveries**: your top 3-5 findings, stated the way a network head wants to hear them, not as code output; (3) **Future Growth Recommendations**: at least 3 concrete, data-backed recommendations for what Raahi Express should do before next peak season. This is the deliverable a hiring manager would actually read, so treat it that way."]}, {"title": "Stretch ideas (optional)", "blurb": "Optional extras, a personal pick of 3 for every buyer.", "count": 6, "sample": ["Propose a new promised-days table per zone x service that would hit about 90% true on-time, and say what it does to the competitiveness of Zone D offers.", "Estimate how many shipments and how many points of on-time % the network would recover if the worst hub's weekday problem disappeared. Show the arithmetic."]}], "premium_count": 5, "total_tasks": 42}$lock$::jsonb
where slug = 'late-again-last-mile-fy2526';

